import{_ as s,C as n,c as a,o as l,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Employee list","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/employees/employee-list.md","filePath":"master/human-resources/employees/employees/employee-list.md","lastUpdated":1791902625000}'),i={name:"master/human-resources/employees/employees/employee-list.md"};function g(p,e,h,d,m,c){const o=n("ImagePopup");return l(),a("div",null,[e[0]||(e[0]=t('<h1 id="employee-list" tabindex="-1">Employee list <a class="header-anchor" href="#employee-list" aria-label="Permalink to &quot;Employee list&quot;">​</a></h1><p>The employee list shows every employee as a card. You use it to find a person fast, to see your own team, and to act on several records at once. Tabs, search, filters and grouping help you narrow a long list.</p><blockquote><p><strong>In simple words:</strong> The list is a wall of employee cards that you can search, filter and group.</p></blockquote><p>Open <code>Employees → Employees</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page opens on the <strong>Default</strong> tab. Click <strong>New Employee</strong> to add a person. See <a href="./add-employee.html">Add an employee</a>.</p>',6)),r(o,{src:"/images1/employees/emp_list_cards.png",alt:"Employees list showing cards with name, job title, email, phone and tags. Priya Sharma's card has no photo, so a gap shows where the photo would be"}),e[1]||(e[1]=t('<p>Each card shows, from top to bottom:</p><ul><li>A photo, when the employee has one, and a checkbox for bulk selection. Without a photo, the card shows a gap in that place.</li><li>The <strong>name</strong> in bold.</li><li>Job title, work email and work phone. They appear only when filled.</li><li>Coloured tag badges.</li><li>Action buttons: a clock icon to schedule an activity, <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>.</li></ul><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><ul><li><strong>Default:</strong> all current employees. It opens first.</li><li><strong>My Team:</strong> employees whose <strong>Manager</strong> is the employee linked to your user.</li><li><strong>My Department:</strong> employees in your own department.</li><li><strong>Archived:</strong> employees you deleted. They stay stored and can be restored.</li><li><strong>Newly Hired:</strong> employees created in the last month.</li></ul><p>The counts depend on who you are. Say your user is linked to the employee Sarah Mitchell. <strong>My Team</strong> then shows the people whose <strong>Manager</strong> is you, which is 9 employees. Someone managed by another employee, such as Robert Diaz under Rachel Kim, is not listed. <strong>My Department</strong> shows people in Sarah&#39;s department, which is only Sarah (Management).</p><p>In the sample data the counts are <strong>Default</strong> 11, <strong>My Team</strong> 9, <strong>My Department</strong> 1, <strong>Archived</strong> 1 and <strong>Newly Hired</strong> 1. <strong>Newly Hired</strong> shows Priya Sharma. <strong>Archived</strong> shows Test Leaver, whose card has a clock icon, <strong>View</strong>, <strong>Edit</strong> and <strong>Restore</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If your user has no linked employee, <strong>My Team</strong> and <strong>My Department</strong> are empty. Set <strong>Related User</strong> on the employee. See <a href="./add-employee.html">Add an employee</a>.</p></div>',7)),r(o,{src:"/images1/employees/emp_list_tabs.png",alt:"Employees tabs Default, My Team, My Department, Archived and Newly Hired with their counts"}),e[2]||(e[2]=t('<h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>Type in the search box. Results update as you type. Search matches <strong>name</strong>, <strong>job title</strong>, <strong>work email</strong> and <strong>work phone</strong>. An <strong>Active filters</strong> bar appears under the search box with a <strong>Search: ...</strong> chip for your text.</p><ul><li><code>Engineer</code> finds every employee whose job title contains Engineer.</li><li><code>555-0104</code> finds the employee with that work phone.</li><li>A department name finds nothing. Use a filter or <strong>Group by</strong> for departments.</li></ul>',3)),r(o,{src:"/images1/employees/emp_list_search.png",alt:"Search box with the word Engineer, the Active filters bar with a Search: Engineer chip and the matching cards"}),e[3]||(e[3]=t('<h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Click the funnel button. The <strong>Filters</strong> panel opens. The panel has three buttons: <strong>Add rule</strong>, <strong>Apply filters</strong> and a red <strong>Reset</strong> at the top right. Click <strong>Apply filters</strong> to use your choices and <strong>Reset</strong> to clear them. A number on the button shows how many filters are on.</p><p>Three simple filters are drop-down lists, set to <strong>All</strong> at first.</p><ul><li><strong>Skills:</strong> employees who have the chosen skill.</li><li><strong>Resumes:</strong> employees with the chosen resume line.</li><li><strong>Timezone:</strong> employees in the chosen time zone.</li></ul><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><p>Click <strong>Add rule</strong> to build your own condition. A rule has a field, an operator and a value. The <strong>Add rule</strong> menu lists many fields, such as <strong>Job Title</strong>, <strong>Department</strong>, <strong>Manager</strong>, <strong>Company</strong>, <strong>Gender</strong>, <strong>Marital Status</strong>, <strong>Departure Date</strong> and <strong>Created At</strong>. It also has an <strong>OR condition</strong> item.</p><p>Add several rules to combine them: an employee must match all of them. Click <strong>OR condition</strong> to add a second group. An employee matching either group is shown.</p><p>Three examples:</p><ol><li><strong>Everyone in one department.</strong> Add rule <strong>Department</strong>, choose the department, click <strong>Apply filters</strong>.</li><li><strong>Staff with a skill.</strong> Open <strong>Skills</strong>, pick <strong>Communication</strong>, click <strong>Apply filters</strong>.</li><li><strong>Married staff in Pune or Mumbai.</strong> Add rule <strong>Marital Status</strong> is <strong>Married</strong>. Then add an <strong>OR condition</strong> group for the cities.</li></ol>',9)),r(o,{src:"/images1/employees/emp_list_filters.png",alt:"Filters panel with Skills, Resumes and Timezone set to All and the Add rule menu open, shown zoomed out to 75%"}),e[4]||(e[4]=t('<h2 id="group-by" tabindex="-1">Group by <a class="header-anchor" href="#group-by" aria-label="Permalink to &quot;Group by&quot;">​</a></h2><p>Open <strong>Group by</strong> and pick a field. Cards gather under collapsible headings labelled <code>Department: Operations</code>, for example. The groups start expanded. Options are <strong>Name</strong>, <strong>Company</strong>, <strong>Manager</strong>, <strong>Coach</strong>, <strong>Department</strong>, <strong>Employment Type</strong>, <strong>Tags</strong>, <strong>Departure Reason</strong>, <strong>Private State</strong>, <strong>Private Country</strong>, <strong>Country</strong>, <strong>State</strong>, <strong>Created At</strong> and <strong>Updated At</strong>. A select next to <strong>Group by</strong> sets the order to <strong>Ascending</strong> or <strong>Descending</strong>.</p><p><strong>Sort by</strong> orders cards by <strong>Name</strong>, <strong>Job Title</strong>, <strong>Work Email</strong> or <strong>Work Phone</strong>.</p>',3)),r(o,{src:"/images1/employees/emp_list_group_by.png",alt:"Group by set to Department with the Ascending or Descending select beside it and employees gathered under Department headings, all except Operations collapsed"}),e[5]||(e[5]=t('<h2 id="per-page" tabindex="-1">Per page <a class="header-anchor" href="#per-page" aria-label="Permalink to &quot;Per page&quot;">​</a></h2><p>At the bottom, choose 18 (default), 36, 72 or All cards per page. A line such as &quot;Showing 1 to 10 of 10 results&quot; tells you the total.</p><h2 id="bulk-actions" tabindex="-1">Bulk actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk actions&quot;">​</a></h2><ol><li>Tick the checkbox on each card, or use the select all box.</li><li>Open the <strong>Bulk actions</strong> menu.</li><li>Choose <strong>Delete selected</strong> or <strong>Force delete selected</strong>.</li></ol><p><strong>Delete selected</strong> moves the employees to <strong>Archived</strong>. <strong>Force delete selected</strong> removes them for good.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Force delete cannot be undone. Use <strong>Delete</strong> when you only want an employee out of the active list.</p></div><h2 id="archive-and-restore" tabindex="-1">Archive and restore <a class="header-anchor" href="#archive-and-restore" aria-label="Permalink to &quot;Archive and restore&quot;">​</a></h2><p>Click <strong>Delete</strong> on a card to archive the employee. Open the <strong>Archived</strong> tab to see archived people. See <a href="./leaving-the-company.html">Leaving the company</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./add-employee.html">Add an employee</a></li><li><a href="./employee-profile.html">Employee profile</a></li><li><a href="./../reporting/skills-report.html">Skills report</a></li><li><a href="./../../../getting-started/search-filter-group.html">Search, filter and group</a></li></ul>',10))])}const b=s(i,[["render",g]]);export{y as __pageData,b as default};
